const errors=[];const warnings=[];const expectedOnboardingDiagnostics=[];
page.on('pageerror',e=>errors.push(e.message));
page.on('console',message=>{const text=message.text();const url=message.location().url;
 if(message.type()==='error'){
  // The logged-out session probe and absent pre-setup profile are deliberate
  // HTTP contracts. Preserve these exact diagnostics; never allow them later.
  const expected=stage==='signup'&&!saved.profile&&((/status of 401/.test(text)&&/\/api\/me(?:\?|$)/.test(url))||(/status of 404/.test(text)&&/\/api\/business-profile(?:\?|$)/.test(url))||(/API request failed.*Business profile not found/.test(text)));
  if(expected)expectedOnboardingDiagnostics.push({message:text,url});else errors.push({message:text,url});
 }
 if(message.type()==='warning')warnings.push(text);
});
async function api(route,method='GET',data){const r=await context.request.fetch(`${origin}${route}`,{method,data,headers:{Origin:origin,...(method==='POST'?{'Idempotency-Key':crypto.randomUUID()}:{})}});assert.ok(r.ok(),`${route}: ${r.status()} ${await r.text()}`);return r.status()===204?null:r.json();}
async function go(route){await page.goto(origin+route,{waitUntil:'networkidle'});await page.evaluate(()=>document.querySelector('[aria-label="Dismiss update prompt"]')?.click());}
async function shot(name,target){if(target)await target.scrollIntoViewIfNeeded();await page.screenshot({path:`${out}/${name}.png`,animations:'disabled'});}
async function response(route,action){const pending=page.waitForResponse(r=>r.request().method()==='POST'&&new URL(r.url()).pathname===route);await action();const r=await pending;assert.ok(r.ok(),`${route}: ${r.status()} ${await r.text()}`);return r.json();}
